import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"诚斋易传","description":"诚斋易传 - 诚斋易传","frontmatter":{"title":"诚斋易传","description":"诚斋易传 - 诚斋易传"},"headers":[],"relativePath":"zh/classics/chengzhai/001.md","filePath":"zh/classics/chengzhai/001.md"}'),r={name:"zh/classics/chengzhai/001.md"};function c(i,a,o,p,d,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"诚斋易传",tabindex:"-1"},[l("诚斋易传 "),e("a",{class:"header-anchor",href:"#诚斋易传","aria-label":"Permalink to “诚斋易传”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：诚斋易传二十卷，宋杨万里撰。万里字廷秀，自号诚斋，吉水人。官至宝谟阁学士致仕。韩侂胄召之不起。开禧间闻北伐启衅，忧愤不食卒。后谥文节。事迹具宋史本传。是书大旨本程氏，而多引史传以证之。初名易外传，后乃改定今名。宋代书肆曾与程传并刊以行，谓之程杨易传。新安陈栎极非之，以为足以耸文士之观瞻，而不足以服穷经士之心。然圣人作易，本以「吉、凶、悔、吝」示人事之所从，舍人事而谈天道，正后儒说易之病，未可以引史说经病万里也。理宗嘉熙元年，尝给札写藏秘阁。元胡一桂作易本义，附录纂疏，博采诸家，乃独不录此书一字，盖以其文士轻之。然万里文章气节，自足千古，此书亦不可磨灭，至今犹在人间。区区门户之见，亦何足为万里轻重欤！乾隆四十二年十月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。诚斋易传原序",-1),e("p",null,"易者何也？易之为言变也。易者，圣人通变之书也。何谓变？盖阴阳，太极之变也；五行，阴阳之变也；人与万物，五行之变也；万事，人与万物之变也。古初以迄于今，万事之变未已也。其作也，一得一失；而其究也，一治一乱。圣人有忧焉，于是幽观其通而逆䌷其图，易之所以作也。易之为言变也。易者，圣人通变之书也。其穷理尽性，其正心修身，其齐家治国，其处显，其傃穷，其居常，其遭变，其参天地、合鬼神，万事之变方来，而变通之道先立。变在彼，变在此，得其道者，蚩可哲，慝可淑，眚可福，危可安，乱可治，致身圣贤而跻世泰和，犹反手也。斯道何道也？中正而已矣。唯中为能中天下之不中，唯正，为能正天下之不正。中正立而万变通，此二帝三王之圣治，孔子颜、孟之圣学也。后世或以事物之变为不足以撄吾心，举而捐之于空虚者，是乱天下者也。不然，以为不足以遁吾术，挈而持之以权谲者，是愈乱天下者也。然则学者将欲通变，于何求通？曰道。于何求道？曰中。于何求中？曰正。于何求正？曰易。于何求易？曰心。愚老矣，尝试与二三子讲之，二三子以为愚之言乎非也。愚闻诸先儒，先儒闻诸三圣，三圣闻诸天。淳熙戊申八月二日，庐陵杨万里序。诚斋易传原序。",-1)])])}const _=t(r,[["render",c]]);export{u as __pageData,_ as default};
